Timeouts de agente.ejemplo:
async def run_tool_with_timeout(call, timeout_s: float = 15.0):
    try:
        return await asyncio.wait_for(execute_tool(call), timeout=timeout_s)
    except asyncio.TimeoutError:
        return {"error": f"Tool {call.name} excedió {timeout_s}s; simplifica o cambia de vía."}

Verificación de acciones del agente.ejemplo:
READ_ONLY_SQL = ("SELECT", "EXPLAIN")
def verify_sql_action(query: str) -> None:
    keyword = query.strip().split()[0].upper()
    if keyword not in READ_ONLY_SQL:
        raise PermissionError(f"Operación {keyword} bloqueada sin aprobación HITL")
